// The server RVA of a client RVA, or 0 when the mapping does not know it (fail closed).
inline std::uint32_t translate(std::uint32_t client) {
    std::size_t lo = 0, hi = kRanges.size();
    while (lo < hi) {
        const std::size_t mid = (lo + hi) / 2;
        const Range& r = kRanges[mid];
        if (client < r.client) hi = mid;
        else if (client >= r.client + r.len) lo = mid + 1;
        else return r.server + (client - r.client);
    }
    return 0;
}

